/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 /opt/homebrew/opt/python@3.14/bin/python3.14 -B -c '
from lib import validate_positive_integer
class IntSubclass(int): pass
for x in (1, 2**4096):
    y = validate_positive_integer(x)
    assert y is x
for x in (True, False, 1.0, \"1\", None, object(), IntSubclass(1)):
    try:
        validate_positive_integer(x)
    except TypeError:
        pass
    else:
        raise AssertionError((x, \"expected TypeError\"))
for x in (0, -1, -(2**4096)):
    try:
        validate_positive_integer(x)
    except ValueError:
        pass
    else:
        raise AssertionError((x, \"expected ValueError\"))
print(\"independent scalar scenarios: OK\")
'"

